const host=document.querySelector('#maquettes');
const copy={fr:{names:['Maison','Villa','Appartement'],rooms:['Bienvenue','Entrez…','Le salon','La cuisine','La chambre','La salle de bain','Les extérieurs'],intro:'Trois adresses, un voyage.',note:'Maison, villa, appartement : laissez le défilement vous guider.',hint:'DÉFILEZ POUR EXPLORER',demo:'Visuels d’illustration · parcours photographique'},en:{names:['House','Villa','Apartment'],rooms:['Welcome','Step inside…','Living room','Kitchen','Bedroom','Bathroom','Outdoor living'],intro:'Three homes. One journey.',note:'House, villa, apartment: follow the journey as you scroll.',hint:'SCROLL TO EXPLORE',demo:'Illustrative imagery · photographic journey'},ar:{names:['منزل','فيلا','شقة'],rooms:['مرحباً بكم','تفضلوا بالدخول','الصالون','المطبخ','غرفة النوم','الحمام','المساحات الخارجية'],intro:'ثلاثة مساكن، رحلة واحدة.',note:'منزل، شقة، فيلا: اكتشف المساحات مع التمرير.',hint:'مرّر للاستكشاف',demo:'صور توضيحية · جولة بالصور'}};
const groups=[['img/maison-facade.webp','img/maison-seuil.webp','panoramas/maison/salon.webp','panoramas/maison/cuisine.webp','panoramas/maison/chambre.webp','panoramas/maison/bain.webp','img/house.webp'],['img/appartement-facade.webp','img/appartement-seuil.webp','panoramas/appartement/salon.webp','panoramas/appartement/cuisine.webp','panoramas/appartement/chambre.webp','panoramas/appartement/bain.webp','img/penthouse.webp'],['img/villa-cutout.webp','img/villa-entrance.webp','panoramas/salon.webp','panoramas/cuisine.webp','panoramas/chambre.webp','panoramas/bain.webp','img/villa.webp']];
[groups[1],groups[2]]=[groups[2],groups[1]];
const reduced=matchMedia('(prefers-reduced-motion: reduce)');const clamp=x=>Math.max(0,Math.min(1,x));
let pending=0;const chapters=[];
host.classList.add('narrative');host.replaceChildren();
const heading=document.createElement('div');heading.className='section-intro';heading.innerHTML='<div><p class="eyebrow">CLÉNORD · COLLECTION</p><h2></h2></div><p class="narrative-intro"></p>';host.append(heading);
groups.forEach((files,i)=>{const section=document.createElement('article');section.className='narrative-chapter';section.innerHTML=`<div class="narrative-pin"><div class="narrative-media"></div><div class="narrative-shade"></div><div class="narrative-top"><span>0${i+1} / 03</span><span class="narrative-name"></span></div><div class="narrative-caption"><p class="eyebrow"></p><h3></h3><p class="narrative-hint"></p></div><div class="narrative-dots" aria-hidden="true">${files.map(()=>'<i></i>').join('')}</div><small class="narrative-disclaimer"></small></div>`;host.append(section);const pin=section.firstElementChild;const media=section.querySelector('.narrative-media');const images=files.map((src,j)=>{const img=new Image();img.src=src;img.alt='';img.loading='eager';img.decoding='async';img.className=j===0?'facade':j===1?'threshold':'';img.addEventListener('load',queue);media.append(img);return img});chapters.push({section,pin,images,i});});
function translate(){const c=copy[document.documentElement.lang]||copy.fr;heading.querySelector('h2').textContent=c.intro;heading.querySelector('.narrative-intro').textContent=c.note;chapters.forEach(o=>{o.section.querySelector('.narrative-name').textContent=c.names[o.i];o.section.querySelector('.eyebrow').textContent=c.names[o.i];o.section.querySelector('.narrative-hint').textContent=c.hint;o.section.querySelector('.narrative-disclaimer').textContent=c.demo});queue()}
function paint(){pending=0;const c=copy[document.documentElement.lang]||copy.fr;const top=document.querySelector('#header').offsetHeight;host.style.setProperty('--narrative-top',top+'px');for(const o of chapters){const r=o.section.getBoundingClientRect();if(r.bottom<0||r.top>innerHeight)continue;const p=clamp((top-r.top)/Math.max(1,r.height-o.pin.offsetHeight));const t=p*(o.images.length-1);let base=Math.floor(t);while(base>0&&(!o.images[base].complete||!o.images[base].naturalWidth))base--;let blend=clamp((t-base-.68)/.32);if(reduced.matches)blend=0;if(o.images[base+1]&&(!o.images[base+1].complete||!o.images[base+1].naturalWidth))blend=0;o.images.forEach((img,j)=>{img.style.opacity=j===base?1:j===base+1?blend:0;const motion=reduced.matches?0:clamp(t-j);img.style.transform=`scale(${1+motion*(j===0?.55:j===1?.38:.045)}) translateY(${-motion*.7}%)`});const idx=blend>.55?Math.min(o.images.length-1,base+1):base;o.section.querySelector('h3').textContent=idx===6&&o.i===2?({fr:'Un espace ouvert',en:'Open-plan living',ar:'مساحة مفتوحة'}[document.documentElement.lang]||'Un espace ouvert'):c.rooms[idx];o.section.querySelectorAll('.narrative-dots i').forEach((dot,j)=>dot.classList.toggle('active',j===idx));}}
function queue(){if(!pending)pending=requestAnimationFrame(paint)}
addEventListener('scroll',queue,{passive:true});addEventListener('resize',queue);new ResizeObserver(queue).observe(host);new MutationObserver(translate).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});reduced.addEventListener('change',queue);translate();
